DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cleanup_old_sessions` ()   BEGIN
    DELETE FROM chat_sessions WHERE last_activity < DATE_SUB(NOW(), INTERVAL 30 DAY);
    DELETE FROM system_logs WHERE created_at < DATE_SUB(NOW(), INTERVAL 90 DAY);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_increment_faq_view` (IN `p_faq_id` INT)   BEGIN
    UPDATE faqs SET view_count = view_count + 1 WHERE id = p_faq_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_log_event` (IN `p_log_type` VARCHAR(20), IN `p_message` TEXT, IN `p_details` JSON)   BEGIN
    INSERT INTO system_logs (log_type, message, details)
    VALUES (p_log_type, p_message, p_details);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_record_feedback` (IN `p_faq_id` INT, IN `p_is_helpful` BOOLEAN)   BEGIN
    IF p_is_helpful THEN
        UPDATE faqs SET helpful_count = helpful_count + 1 WHERE id = p_faq_id;
    ELSE
        UPDATE faqs SET not_helpful_count = not_helpful_count + 1 WHERE id = p_faq_id;
    END IF;
END$$

DELIMITER ;

