) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `faqs`
--

INSERT INTO `faqs` (`id`, `category_id`, `question`, `answer`, `keywords`, `source_url`, `view_count`, `helpful_count`, `not_helpful_count`, `is_active`, `created_at`, `updated_at`) VALUES
(325, 1, 'Apa saja layanan yang tersedia di Dispusipda Pekanbaru?', 'Dispusipda Pekanbaru menyediakan berbagai layanan: 1) Layanan Sirkulasi (peminjaman/pengembalian buku), 2) Layanan Umum dengan 18.114 judul koleksi, 3) Layanan Anak dengan 8.828 judul koleksi, 4) Layanan Referensi, 5) Layanan i-Pekanbaru (perpustakaan digital dengan 8.527 e-book), 6) Layanan Penelusuran Literatur menggunakan OPAC, 7) Layanan Perpustakaan Keliling (MPK), dan 8) Layanan Kearsipan termasuk akses SIKN-JIKN.', 'layanan, fasilitas, tersedia, dispusipda, jenis layanan', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(326, 1, 'Apa itu Layanan Sirkulasi?', 'Layanan Sirkulasi adalah kegiatan melayani pengguna perpustakaan dalam peminjaman dan pengembalian bahan pustaka beserta penyelesaian administrasinya seperti pendaftaran anggota perpustakaan.', 'sirkulasi, peminjaman, pengembalian, administrasi', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(327, 1, 'Apa itu Layanan Umum di perpustakaan?', 'Layanan Umum adalah layanan yang menyediakan bahan perpustakaan untuk masyarakat umum remaja hingga dewasa. Layanan Umum DISPUSIP memiliki 18.114 judul koleksi perpustakaan.', 'layanan umum, remaja, dewasa, koleksi umum', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(328, 1, 'Apa itu Layanan Anak di perpustakaan?', 'Layanan Anak adalah pelayanan perpustakaan yang ditujukan untuk anak berumur 12-13 tahun, didalamnya termasuk kegiatan mendongeng. Layanan Anak DISPUSIP memiliki 8.828 judul koleksi perpustakaan.', 'layanan anak, anak-anak, mendongeng, koleksi anak', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(329, 1, 'Apa itu Layanan Referensi?', 'Layanan Referensi adalah layanan yang diberikan kepada pengguna perpustakaan yang bertujuan untuk membantu mereka dalam penelusuran informasi rujukan. Layanan ini membantu menelusur informasi secara lebih spesifik dengan pilihan subyek yang lebih luas.', 'referensi, rujukan, penelusuran, informasi spesifik', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(330, 1, 'Apa itu Layanan i-Pekanbaru?', 'Layanan i-Pekanbaru adalah perpustakaan digital berbasis aplikasi yang menyediakan 8.527 eksemplar e-book. Aplikasi iPekanbaru tersedia untuk Android dan Desktop yang dapat diunduh secara gratis melalui link: https://ipekanbaru.moco.co.id/', 'ipekanbaru, i-pekanbaru, digital, aplikasi, ebook, playstore, download', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(331, 1, 'Apa itu Layanan Penelusuran Literatur?', 'Layanan Penelusuran Literatur adalah kegiatan mencari atau menemukan kembali informasi kepustakaan mengenai suatu bidang tertentu yang ada di perpustakaan dengan menggunakan bantuan OPAC (Online Public Access Catalogue). Anda dapat mengakses katalog online di: https://pustaka.pekanbaru.go.id/Tenas.Efendy/opac/', 'penelusuran literatur, opac, katalog online, cari buku', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(332, 1, 'Apa itu Layanan Perpustakaan Keliling?', 'Layanan Perpustakaan Keliling adalah kegiatan layanan perpustakaan yang bergerak dari satu tempat ke tempat lain dengan menggunakan Mobil Perpustakaan Keliling (MPK). Dispusipda juga memiliki layanan SipuSiaga (Sinergikan Perpustakaan Siap Antar Kewarga) yang siap melayani kebutuhan komunitas dan masyarakat.', 'perpustakaan keliling, mobil perpustakaan, mpk, keliling, sipusiaga', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(333, 1, 'Apa itu SipuSiaga atau Pusteling?', 'SipuSiaga (Sinergikan Perpustakaan Siap Antar Kewarga) atau Pusteling adalah sistem perpustakaan siaga yang siap melayani kebutuhan komunitas dan masyarakat. Layanan ini menggunakan Mobil Perpustakaan Keliling yang dapat datang ke lokasi Anda. Untuk mengundang Pusteling, hubungi Admin di nomor: 0813 7809 1515.', 'sipusiaga, pusteling, perpustakaan siaga, mobil perpustakaan, keliling, antar kewarga', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(334, 1, 'Bagaimana cara mengundang Pusteling atau mobil perpustakaan keliling?', 'Untuk mengundang Pusteling (Perpustakaan Keliling) ke lokasi Anda, silakan hubungi Admin SipuSiaga di nomor: 0813 7809 1515. Layanan ini siap melayani kebutuhan komunitas dan masyarakat di berbagai lokasi.', 'undang pusteling, hubungi, nomor telepon, kontak pusteling, mobil perpustakaan', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(335, 1, 'Bagaimana cara meminjam buku di perpustakaan?', 'Untuk meminjam buku: 1) Pastikan Anda sudah menjadi anggota dan memiliki Kartu Tanda Anggota (KTA), 2) Pilih buku yang ingin dipinjam, 3) Bawa buku ke meja sirkulasi bersama KTA, 4) Petugas akan memproses peminjaman. Batas peminjaman maksimal 2 eksemplar dalam jangka 1 minggu. Kegiatan membaca/meminjam/mengembalikan/memperpanjang buku wajib menggunakan Kartu Tanda Anggota.', 'pinjam, meminjam, cara pinjam, buku', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(336, 1, 'Berapa lama batas waktu peminjaman buku?', 'Batas waktu peminjaman buku adalah 1 minggu. Anda dapat meminjam maksimal 2 (dua) eksemplar buku dalam jangka waktu tersebut.', 'batas, waktu, durasi, peminjaman, hari, minggu', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(337, 1, 'Berapa banyak buku yang bisa dipinjam?', 'Setiap anggota perpustakaan berhak meminjam koleksi maksimal 2 (dua) eksemplar dalam jangka 1 minggu.', 'jumlah pinjam, maksimal, berapa buku, eksemplar', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(338, 1, 'Bagaimana cara memperpanjang peminjaman buku?', 'Perpanjangan pinjaman buku perpustakaan dapat dilakukan maksimal 1x dalam jangka 1 minggu. Anda bisa datang langsung ke perpustakaan dengan membawa buku dan Kartu Tanda Anggota (KTA).', 'perpanjang, perpanjangan, extend', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(339, 1, 'Apakah ada denda keterlambatan pengembalian buku?', 'Ya, setiap anggota perpustakaan wajib mengembalikan koleksi perpustakaan sesuai waktu yang telah ditetapkan. Jika terlambat atau buku hilang, anggota bertanggungjawab dengan mengganti buku atau membayar denda setara.', 'denda, terlambat, keterlambatan, telat, hilang, ganti', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(340, 1, 'Apa yang harus dilakukan jika buku perpustakaan hilang?', 'Setiap anggota perpustakaan bertanggungjawab atas koleksi perpustakaan yang hilang dengan mengganti buku atau membayar denda setara dengan nilai buku.', 'hilang, kehilangan, buku hilang, ganti rugi', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(341, 1, 'Apa saja hak anggota perpustakaan?', 'Setiap anggota perpustakaan berhak: 1) Menggunakan fasilitas perpustakaan, 2) Meminjam koleksi maksimal 2 (dua) eksemplar dalam jangka 1 minggu, 3) Memperpanjang pinjaman buku perpustakaan maksimal 1x dalam jangka 1 minggu.', 'hak anggota, berhak, fasilitas, hak member', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(342, 1, 'Apa saja kewajiban anggota perpustakaan?', 'Setiap anggota perpustakaan wajib: 1) Menjaga fasilitas perpustakaan dan mempergunakannya sebaik-baiknya, 2) Mengembalikan koleksi perpustakaan sesuai waktu yang telah ditetapkan, 3) Bertanggungjawab atas koleksi perpustakaan yang hilang dengan mengganti atau membayar denda setara.', 'kewajiban, wajib, tanggung jawab, aturan', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(343, 2, 'Bagaimana cara mendaftar menjadi anggota perpustakaan?', 'Untuk mendaftar menjadi anggota dan membuat Kartu Tanda Anggota (KTA): 1) Mengisi formulir KTA pada link https://bit.ly/2T0EJcO, 2) Membawa formulir yang sudah diisi dan dilengkapi tanda tangan (untuk pelajar: stempel kepala sekolah/tata usaha), 3) Melampirkan fotokopi KTP/SIM/Kartu Pelajar/Kartu Keluarga (pilih salah satu), 4) Berfoto di ruang foto untuk KTA dan penyerahan KTA.', 'daftar, mendaftar, registrasi, anggota, member, kta, kartu', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(344, 2, 'Dimana link untuk mendaftar anggota perpustakaan online?', 'Anda dapat mengisi formulir pendaftaran anggota perpustakaan (KTA) secara online melalui link: https://bit.ly/2T0EJcO', 'link, online, formulir, daftar online, website', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(345, 2, 'Apa saja syarat menjadi anggota perpustakaan?', 'Syarat menjadi anggota: 1) Mengisi formulir KTA pada link https://bit.ly/2T0EJcO, 2) Membawa formulir yang sudah diisi dengan tanda tangan (pelajar: ditambah stempel kepala sekolah/tata usaha), 3) Melampirkan fotokopi KTP/SIM/Kartu Pelajar/Kartu Keluarga (pilih salah satu), 4) Berfoto di ruang foto perpustakaan untuk KTA.', 'syarat, ketentuan, persyaratan, anggota, dokumen', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(346, 2, 'Apa saja dokumen yang diperlukan untuk mendaftar anggota?', 'Dokumen yang diperlukan untuk mendaftar anggota perpustakaan: 1) Formulir KTA yang sudah diisi (dari link https://bit.ly/2T0EJcO), 2) Fotokopi KTP/SIM/Kartu Pelajar/Kartu Keluarga (pilih salah satu), 3) Untuk pelajar: formulir harus dilengkapi tanda tangan dan stempel kepala sekolah/tata usaha.', 'dokumen, berkas, persyaratan, ktp, sim, kartu pelajar', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(347, 2, 'Bagaimana syarat pendaftaran untuk pelajar?', 'Untuk pelajar yang ingin mendaftar anggota perpustakaan: 1) Mengisi formulir KTA dari link https://bit.ly/2T0EJcO, 2) Formulir harus dilengkapi dengan tanda tangan dan stempel kepala sekolah atau tata usaha, 3) Melampirkan fotokopi Kartu Pelajar atau Kartu Keluarga, 4) Berfoto di ruang foto perpustakaan.', 'pelajar, siswa, sekolah, stempel, mahasiswa', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(348, 2, 'Apa itu Kartu Tanda Anggota (KTA)?', 'Kartu Tanda Anggota (KTA) adalah kartu identitas keanggotaan perpustakaan yang wajib digunakan untuk kegiatan membaca, meminjam, mengembalikan, dan memperpanjang buku di perpustakaan.', 'kta, kartu anggota, kartu member, kartu perpustakaan', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(349, 2, 'Apakah pendaftaran anggota perpustakaan gratis?', 'Ya, pendaftaran anggota perpustakaan Dispusipda Pekanbaru GRATIS untuk seluruh masyarakat. Tidak ada biaya pembuatan Kartu Tanda Anggota (KTA).', 'gratis, biaya, bayar, free, tarif', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(350, 4, 'Jam berapa perpustakaan buka dan tutup?', 'Jadwal layanan Perpustakaan Tenas Effendy Dispusipda Pekanbaru: Senin-Kamis: 08.00-16.00 WIB, Jumat: 08.00-16.30 WIB (istirahat 11.30-13.30 WIB), Sabtu-Ahad: 08.00-14.00 WIB.', 'jam, buka, tutup, operasional, waktu, jadwal', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(351, 4, 'Jam buka perpustakaan hari Senin sampai Kamis?', 'Perpustakaan Tenas Effendy buka hari Senin sampai Kamis pukul 08.00 - 16.00 WIB.', 'senin, selasa, rabu, kamis, weekday', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(352, 4, 'Jam buka perpustakaan hari Jumat?', 'Perpustakaan Tenas Effendy buka hari Jumat pukul 08.00 - 16.30 WIB, dengan jam istirahat pukul 11.30 - 13.30 WIB.', 'jumat, istirahat, sholat jumat', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(353, 4, 'Apakah perpustakaan buka di hari Sabtu dan Minggu?', 'Ya, perpustakaan buka di akhir pekan! Perpustakaan Tenas Effendy buka hari Sabtu dan Ahad (Minggu) pukul 08.00 - 14.00 WIB.', 'sabtu, minggu, ahad, weekend, akhir pekan, libur', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(354, 4, 'Apa nama perpustakaan utama Dispusipda Pekanbaru?', 'Perpustakaan utama Dispusipda Pekanbaru bernama Perpustakaan Tenas Effendy.', 'nama perpustakaan, tenas effendy, perpustakaan utama', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(355, 6, 'Dimana alamat Dispusipda Pekanbaru?', 'Alamat Dispusipda Pekanbaru (Perpustakaan Tenas Effendy) adalah: Jl. Dr. Sutomo No. 1, Kelurahan Suka Mulia, Kecamatan Sail, Kota Pekanbaru, Riau 28125. Lokasi ini berada di pusat kota Pekanbaru dan mudah dijangkau.', 'alamat, lokasi, dimana, jalan, sutomo, gedung, tempat', '', 1, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:56'),
(356, 6, 'Bagaimana cara ke Dispusipda Pekanbaru?', 'Dispusipda Pekanbaru (Perpustakaan Tenas Effendy) berlokasi di Jl. Dr. Sutomo No. 1, Kecamatan Sail, Pekanbaru. Perpustakaan ini berada di pusat kota dan dapat dijangkau dengan kendaraan umum maupun pribadi. Untuk navigasi, cari \"Perpustakaan Tenas Effendy Pekanbaru\" di Google Maps.', 'cara ke, rute, navigasi, menuju, google maps', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(357, 6, 'Bagaimana cara menghubungi Dispusipda Pekanbaru?', 'Anda dapat menghubungi Dispusipda Pekanbaru melalui: Email: bpadkotapekanbaru@gmail.com, Website: dispusipda.pekanbaru.go.id, YouTube: Dispusip Pekanbaru, Instagram: @dispusippku, Twitter: @DispusipPKU, Facebook: dispusip.pekanbaru', 'kontak, hubungi, telepon, email, wa, whatsapp, sosmed', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(358, 6, 'Apa email Dispusipda Pekanbaru?', 'Email resmi Dispusipda Pekanbaru adalah: bpadkotapekanbaru@gmail.com', 'email, surat elektronik, gmail', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(359, 6, 'Apa website resmi Dispusipda Pekanbaru?', 'Website resmi Dispusipda Pekanbaru adalah: dispusipda.pekanbaru.go.id', 'website, web, situs, alamat web', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(360, 6, 'Apa akun Instagram Dispusipda Pekanbaru?', 'Akun Instagram resmi Dispusipda Pekanbaru adalah: @dispusippku', 'instagram, ig, sosmed, media sosial', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(361, 6, 'Apa akun media sosial Dispusipda Pekanbaru?', 'Media sosial resmi Dispusipda Pekanbaru: YouTube: Dispusip Pekanbaru, Instagram: @dispusippku, Twitter: @DispusipPKU, Facebook: dispusip.pekanbaru', 'sosmed, media sosial, youtube, twitter, facebook', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(362, 3, 'Berapa jumlah koleksi perpustakaan Dispusipda?', 'Dispusipda Pekanbaru memiliki koleksi yang lengkap: Layanan Umum memiliki 18.114 judul koleksi, Layanan Anak memiliki 8.828 judul koleksi, dan Layanan i-Pekanbaru (digital) memiliki 8.527 eksemplar e-book.', 'jumlah koleksi, berapa buku, total koleksi', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(363, 3, 'Apa saja jenis koleksi yang tersedia di perpustakaan?', 'Dispusipda Pekanbaru memiliki berbagai koleksi: Koleksi Umum (18.114 judul) untuk remaja dan dewasa, Koleksi Anak (8.828 judul) untuk anak usia 12-13 tahun, Koleksi Referensi untuk penelusuran informasi rujukan, dan Koleksi Digital/E-book (8.527 eksemplar) melalui aplikasi i-Pekanbaru.', 'koleksi, buku, jenis, macam, tersedia', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(364, 3, 'Bagaimana cara mencari buku di katalog perpustakaan?', 'Anda dapat mencari buku menggunakan Layanan Penelusuran Literatur melalui OPAC (Online Public Access Catalogue) di website: https://pustaka.pekanbaru.go.id/Tenas.Efendy/opac/. OPAC membantu menemukan kembali informasi kepustakaan mengenai suatu bidang tertentu yang ada di perpustakaan.', 'cari, katalog, opac, search, pencarian', '', 1, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:30:28'),
(365, 3, 'Dimana saya bisa melihat daftar buku yang tersedia di perpustakaan?', 'Anda dapat melihat daftar buku dan koleksi perpustakaan melalui OPAC (Online Public Access Catalogue) di website: https://pustaka.pekanbaru.go.id/Tenas.Efendy/opac/. Website ini menyediakan katalog lengkap koleksi Dispusipda Pekanbaru.', 'daftar buku, lihat buku, katalog, koleksi tersedia, opac', '', 1, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:30:28'),
(366, 3, 'Bagaimana cara menyarankan buku untuk perpustakaan?', 'Jika Anda ingin menyarankan buku untuk ditambahkan ke koleksi perpustakaan, silakan isi formulir saran buku melalui link: https://docs.google.com/forms/d/e/1FAIpQLSd_Kw9UpL2zIHjlzBDHBrDORrlE-ETg09JG0jrYTbUvlSXN-A/viewform. Masukan Anda sangat berharga untuk pengembangan koleksi perpustakaan.', 'saran buku, rekomendasi, usul buku, tambah koleksi, form saran', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(367, 8, 'Apakah ada layanan perpustakaan digital atau e-book?', 'Ya, Dispusipda Pekanbaru menyediakan layanan perpustakaan digital melalui aplikasi i-Pekanbaru. Aplikasi ini menyediakan 8.527 eksemplar e-book yang dapat diakses secara gratis. Download aplikasi di: https://ipekanbaru.moco.co.id/ (tersedia untuk Android dan Desktop).', 'digital, online, e-book, ebook, internet, e-library', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(368, 8, 'Bagaimana cara mengakses e-book di Dispusipda?', 'Untuk mengakses e-book, download aplikasi i-Pekanbaru melalui link: https://ipekanbaru.moco.co.id/. Aplikasi ini tersedia untuk Android dan Desktop secara gratis. Aplikasi menyediakan 8.527 eksemplar e-book yang dapat dibaca kapan saja dan dimana saja.', 'akses ebook, download, unduh, baca online', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(369, 8, 'Dimana saya bisa download aplikasi iPekanbaru?', 'Anda dapat mendownload aplikasi iPekanbaru (perpustakaan digital) melalui link: https://ipekanbaru.moco.co.id/. Aplikasi tersedia untuk Android dan Desktop. Dengan aplikasi ini, Anda bisa membaca 8.527 e-book secara gratis.', 'download ipekanbaru, unduh aplikasi, playstore, app store', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(370, 8, 'Apakah ada layanan buku bersuara atau audiobook?', 'Ya, Dispusipda Pekanbaru menyediakan layanan buku anak bersuara (audiobook) melalui platform Membara. Anda dapat mengakses buku anak bersuara di website: https://membara.perpustakaanterbaik.com/. Layanan ini memudahkan anak-anak mendengarkan cerita dan buku tanpa harus membaca.', 'audiobook, buku bersuara, audio, dengar buku, membara, buku anak', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(371, 8, 'Apa itu Membara?', 'Membara adalah platform buku anak bersuara (audiobook untuk anak-anak) yang disediakan oleh Dispusipda Pekanbaru. Anak-anak dapat mendengarkan berbagai koleksi buku cerita dan edukasi dalam format audio melalui website: https://membara.perpustakaanterbaik.com/. Layanan ini sangat cocok untuk menumbuhkan minat baca anak sejak dini.', 'membara, buku bersuara, audiobook, platform audio, buku anak', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(372, 8, 'Bagaimana cara mendengarkan buku bersuara?', 'Untuk mendengarkan buku anak bersuara (audiobook), kunjungi website Membara di: https://membara.perpustakaanterbaik.com/. Di platform ini anak-anak bisa menemukan berbagai koleksi buku cerita dalam format audio yang bisa didengarkan kapan saja.', 'cara audiobook, dengar buku, mendengarkan, audio, anak', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(373, 8, 'Apa itu OPAC?', 'OPAC adalah singkatan dari Online Public Access Catalogue. OPAC adalah sistem katalog online yang digunakan dalam Layanan Penelusuran Literatur untuk mencari atau menemukan kembali informasi kepustakaan. Akses OPAC Dispusipda di: https://pustaka.pekanbaru.go.id/Tenas.Efendy/opac/', 'opac, katalog online, pencarian buku, catalogue', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(374, 7, 'Apa saja program dan kegiatan di perpustakaan?', 'Dispusipda Pekanbaru menyelenggarakan berbagai program seperti: kegiatan mendongeng di Layanan Anak, Layanan Perpustakaan Keliling menggunakan Mobil Perpustakaan Keliling (MPK) yang bergerak ke berbagai tempat, serta layanan literasi digital melalui aplikasi i-Pekanbaru.', 'program, kegiatan, acara, event, aktivitas', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(375, 7, 'Apakah ada kegiatan mendongeng untuk anak?', 'Ya, kegiatan mendongeng tersedia di Layanan Anak perpustakaan. Layanan Anak ditujukan untuk anak berumur 12-13 tahun dan memiliki 8.828 judul koleksi perpustakaan khusus anak.', 'mendongeng, dongeng, anak, storytelling', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(376, 7, 'Apa saja percobaan sains yang tersedia di perpustakaan?', 'Dispusipda Pekanbaru menyediakan manual book percobaan sains sederhana untuk anak-anak, antara lain: 1) Percobaan Lava Lamp - membuat lampu lava dari bahan sederhana, 2) Percobaan Rainbow Lava - variasi lava lamp dengan efek pelangi. Percobaan ini mengajarkan konsep sains seperti densitas (massa jenis), polaritas molekul, dan reaksi kimia sederhana.', 'percobaan sains, eksperimen, lava lamp, rainbow lava, sains anak', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(377, 7, 'Apa itu percobaan Lava Lamp?', 'Lava Lamp adalah percobaan sains sederhana yang mengajarkan konsep densitas dan reaksi kimia. Bahan yang dibutuhkan: botol/gelas bening, air (1/4 bagian), minyak goreng (3/4 bagian), pewarna makanan, dan tablet effervescent. Cara membuat: 1) Tuang air ke botol (1/4), 2) Tambah minyak (3/4), 3) Tunggu terpisah, 4) Teteskan pewarna, 5) Masukkan tablet effervescent dan amati gelembung berwarna naik turun seperti lava.', 'lava lamp, lampu lava, percobaan, eksperimen, minyak air', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(378, 7, 'Bagaimana cara membuat Lava Lamp?', 'Langkah membuat Lava Lamp: 1) Siapkan botol/gelas bening, 2) Tuang air hingga 1/4 bagian, 3) Tambahkan minyak goreng hingga 3/4 bagian, 4) Tunggu hingga air dan minyak terpisah sempurna, 5) Teteskan pewarna makanan (akan turun ke air), 6) Patahkan tablet effervescent dan masukkan, 7) Amati gelembung berwarna yang naik turun seperti lava lamp!', 'cara membuat lava lamp, langkah lava lamp, tutorial', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(379, 7, 'Apa bahan-bahan untuk membuat Lava Lamp?', 'Bahan untuk percobaan Lava Lamp: 1) Botol atau gelas bening/transparan, 2) Air secukupnya (1/4 bagian), 3) Minyak goreng (3/4 bagian), 4) Pewarna makanan (warna sesuai selera), 5) Tablet effervescent (seperti vitamin C effervescent). Semua bahan mudah didapat di rumah atau minimarket.', 'bahan lava lamp, alat lava lamp, perlengkapan', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(380, 7, 'Mengapa minyak dan air tidak bisa bercampur di Lava Lamp?', 'Minyak dan air tidak bisa bercampur karena perbedaan polaritas molekul. Air adalah molekul polar sedangkan minyak adalah molekul non-polar. Selain itu, minyak memiliki densitas (massa jenis) lebih rendah dari air sehingga minyak selalu mengapung di atas air. Inilah prinsip sains di balik percobaan Lava Lamp.', 'polaritas, densitas, massa jenis, sains lava lamp, mengapa', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(381, 7, 'Bagaimana prinsip kerja Lava Lamp?', 'Prinsip kerja Lava Lamp: 1) Air dan minyak terpisah karena perbedaan densitas dan polaritas, 2) Pewarna larut di air (bukan minyak) karena sama-sama polar, 3) Tablet effervescent bereaksi dengan air menghasilkan gas CO2, 4) Gelembung gas membawa air berwarna naik ke permukaan, 5) Setelah gas lepas, air turun kembali. Siklus ini menciptakan efek \"lava\" yang bergerak naik-turun.', 'prinsip lava lamp, cara kerja, mekanisme, sains', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(382, 7, 'Apa itu percobaan Rainbow Lava?', 'Rainbow Lava adalah variasi percobaan Lava Lamp dengan efek pelangi/multi warna. Prinsipnya sama dengan Lava Lamp biasa, namun menggunakan beberapa warna pewarna makanan berbeda untuk menciptakan efek pelangi yang lebih menarik. Percobaan ini cocok untuk anak-anak karena lebih colorful dan menyenangkan.', 'rainbow lava, pelangi, lava warna-warni, percobaan anak', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(383, 7, 'Bagaimana cara membuat Rainbow Lava?', 'Cara membuat Rainbow Lava: 1) Siapkan botol/gelas bening, 2) Tuang air (1/4 bagian), 3) Tambah minyak goreng (3/4 bagian), 4) Tunggu terpisah, 5) Teteskan beberapa warna pewarna makanan berbeda (merah, kuning, biru, hijau), 6) Masukkan tablet effervescent, 7) Amati gelembung warna-warni seperti pelangi yang bergerak naik turun!', 'cara rainbow lava, tutorial rainbow, langkah', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(384, 7, 'Untuk usia berapa percobaan Lava Lamp cocok?', 'Percobaan Lava Lamp dan Rainbow Lava cocok untuk anak usia SD hingga SMP (sekitar 7-15 tahun). Percobaan ini aman karena menggunakan bahan-bahan rumah tangga yang tidak berbahaya. Namun, untuk anak usia lebih kecil sebaiknya didampingi orang dewasa, terutama saat menggunakan tablet effervescent.', 'usia, umur, anak sd, anak smp, cocok untuk', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(385, 7, 'Apa manfaat percobaan sains Lava Lamp untuk anak?', 'Manfaat percobaan Lava Lamp untuk anak: 1) Mengajarkan konsep densitas/massa jenis, 2) Memahami polaritas molekul (polar vs non-polar), 3) Mengenal reaksi kimia sederhana (effervescent + air = CO2), 4) Melatih keterampilan observasi, 5) Menumbuhkan minat sains sejak dini, 6) Aktivitas edukatif yang menyenangkan.', 'manfaat, kegunaan, belajar sains, edukasi', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(386, 7, 'Dimana bisa mendapatkan manual book percobaan sains?', 'Manual book percobaan sains seperti Lava Lamp dan Rainbow Lava tersedia di Dispusipda Pekanbaru, khususnya di Layanan Anak. Anda juga dapat mengikuti kegiatan sains dan eksperimen yang diadakan oleh perpustakaan. Untuk informasi jadwal kegiatan, silakan hubungi Dispusipda atau cek media sosial @dispusippku.', 'manual book, buku panduan, dapat dimana, lokasi', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(387, NULL, 'Apa saja layanan kearsipan di Dispusipda Pekanbaru?', 'Dispusipda Pekanbaru menyediakan Layanan Kearsipan yang mencakup: 1) Konsultasi pengelolaan arsip untuk instansi/lembaga, 2) Bimbingan teknis kearsipan, 3) Akses informasi arsip statis melalui SIKN-JIKN, 4) Penyimpanan dan pemeliharaan arsip daerah, 5) Alih media arsip (digitalisasi).', 'layanan kearsipan, arsip, konsultasi, bimbingan teknis', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(388, NULL, 'Apa itu SIKN-JIKN?', 'SIKN (Sistem Informasi Kearsipan Nasional) adalah sistem informasi kearsipan nasional yang dibangun oleh ANRI untuk menyediakan akses informasi arsip statis secara elektronik. JIKN (Jaringan Informasi Kearsipan Nasional) adalah jaringan yang menghubungkan sistem kearsipan antar lembaga. Dispusipda Pekanbaru tergabung dalam SIKN-JIKN untuk mempermudah akses informasi arsip.', 'sikn, jikn, sistem informasi kearsipan, arsip nasional, anri', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(389, NULL, 'Bagaimana cara mengakses arsip di Dispusipda?', 'Untuk mengakses arsip statis di Dispusipda Pekanbaru, Anda dapat: 1) Datang langsung ke ruang layanan kearsipan dengan membawa identitas diri, 2) Mengakses arsip digital melalui SIKN-JIKN, 3) Mengajukan permohonan tertulis untuk arsip tertentu. Layanan ini terbuka untuk peneliti, mahasiswa, dan masyarakat umum.', 'akses arsip, cara, lihat arsip, penelitian', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(390, NULL, 'Apakah Dispusipda melayani konsultasi kearsipan?', 'Ya, Dispusipda Pekanbaru menyediakan layanan konsultasi kearsipan untuk instansi pemerintah, lembaga swasta, dan masyarakat. Konsultasi meliputi: pengelolaan arsip, penyusutan arsip, jadwal retensi arsip (JRA), dan alih media arsip. Silakan hubungi Dispusipda untuk membuat janji konsultasi.', 'konsultasi, bimbingan, arsip, pengelolaan arsip', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(391, NULL, 'Apa itu arsip statis?', 'Arsip statis adalah arsip yang dihasilkan oleh pencipta arsip karena memiliki nilai guna kesejarahan, telah habis retensinya, dan berketerangan dipermanenkan. Arsip statis disimpan secara permanen di lembaga kearsipan seperti Dispusipda dan dapat diakses oleh publik untuk kepentingan penelitian dan pendidikan.', 'arsip statis, permanen, kesejarahan, nilai guna', '', 0, 0, 0, 1, '2025-12-24 10:29:02', '2025-12-24 10:29:02'),
(392, NULL, 'Apa itu arsip dinamis?', 'Arsip dinamis adalah arsip yang digunakan secara langsung dalam kegiatan pencipta arsip dan disimpan selama jangka waktu tertentu. Arsip dinamis terbagi menjadi: 1) Arsip aktif - masih sering digunakan, 2) Arsip inaktif - jarang digunakan tapi masih diperlukan. Dispusipda dapat memberikan bimbingan pengelolaan arsip dinamis.', 'arsip dinamis, aktif, inaktif, pengelolaan', '', 0, 0, 0, 1, '2025-12-24 10:29:03', '2025-12-24 10:29:03'),
(393, NULL, 'Bagaimana cara mendapatkan bimbingan teknis kearsipan?', 'Untuk mendapatkan bimbingan teknis kearsipan dari Dispusipda Pekanbaru: 1) Ajukan permohonan tertulis ke Dispusipda, 2) Jelaskan kebutuhan bimbingan (pengelolaan arsip, penyusutan, alih media, dll), 3) Koordinasi jadwal dengan tim kearsipan. Layanan ini tersedia untuk instansi pemerintah dan swasta.', 'bimbingan teknis, bimtek, pelatihan, kearsipan', '', 0, 0, 0, 1, '2025-12-24 10:29:03', '2025-12-24 10:29:03'),
(394, 9, 'Apa itu Dispusipda Pekanbaru?', 'Dispusipda (Dinas Perpustakaan dan Kearsipan) Kota Pekanbaru adalah instansi pemerintah yang bertugas mengelola perpustakaan umum dan kearsipan daerah. Perpustakaan utamanya bernama Perpustakaan Tenas Effendy yang menyediakan 7 jenis layanan untuk masyarakat.', 'dispusipda, apa, perpustakaan, dinas', '', 0, 0, 0, 1, '2025-12-24 10:29:03', '2025-12-24 10:29:03'),
(395, 9, 'Siapa saja yang boleh mengunjungi perpustakaan?', 'Perpustakaan Dispusipda Pekanbaru terbuka untuk umum. Siapa saja boleh berkunjung untuk membaca di tempat. Untuk meminjam buku, Anda perlu membuat Kartu Tanda Anggota (KTA) terlebih dahulu melalui link https://bit.ly/2T0EJcO.', 'siapa, boleh, umum, pengunjung, akses', '', 0, 0, 0, 1, '2025-12-24 10:29:03', '2025-12-24 10:29:03');

