--
-- Table structure for table `faq_embeddings`
--

CREATE TABLE `faq_embeddings` (
  `id` int(11) NOT NULL,
  `faq_id` int(11) NOT NULL,
  `embedding_vector` longblob NOT NULL,
  `embedding_model` varchar(200) DEFAULT 'sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2',
  `embedding_dimension` int(11) DEFAULT 384,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

