--
-- Stand-in structure for view `v_daily_chat_stats`
-- (See below for the actual view)
--
CREATE TABLE `v_daily_chat_stats` (
`date` date
,`unique_sessions` bigint(21)
,`total_messages` bigint(21)
,`user_messages` decimal(22,0)
,`bot_responses` decimal(22,0)
,`avg_response_time_ms` decimal(14,4)
);

-- --------------------------------------------------------

--
-- Stand-in structure for view `v_faq_statistics`
-- (See below for the actual view)
--
CREATE TABLE `v_faq_statistics` (
`id` int(11)
,`question` text
,`category` varchar(100)
,`view_count` int(11)
,`helpful_count` int(11)
,`not_helpful_count` int(11)
,`helpfulness_rate` decimal(16,2)
);

-- --------------------------------------------------------

--
-- Structure for view `v_daily_chat_stats`
--
DROP TABLE IF EXISTS `v_daily_chat_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_daily_chat_stats`  AS SELECT cast(`chat_messages`.`created_at` as date) AS `date`, count(distinct `chat_messages`.`session_id`) AS `unique_sessions`, count(0) AS `total_messages`, sum(case when `chat_messages`.`role` = 'user' then 1 else 0 end) AS `user_messages`, sum(case when `chat_messages`.`role` = 'assistant' then 1 else 0 end) AS `bot_responses`, avg(`chat_messages`.`response_time_ms`) AS `avg_response_time_ms` FROM `chat_messages` GROUP BY cast(`chat_messages`.`created_at` as date) ORDER BY cast(`chat_messages`.`created_at` as date) DESC ;

-- --------------------------------------------------------

--
-- Structure for view `v_faq_statistics`
