DROP TABLE IF EXISTS `v_faq_statistics`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_faq_statistics`  AS SELECT `f`.`id` AS `id`, `f`.`question` AS `question`, `c`.`name` AS `category`, `f`.`view_count` AS `view_count`, `f`.`helpful_count` AS `helpful_count`, `f`.`not_helpful_count` AS `not_helpful_count`, CASE WHEN `f`.`helpful_count` + `f`.`not_helpful_count` > 0 THEN round(`f`.`helpful_count` * 100.0 / (`f`.`helpful_count` + `f`.`not_helpful_count`),2) ELSE 0 END AS `helpfulness_rate` FROM (`faqs` `f` left join `categories` `c` on(`f`.`category_id` = `c`.`id`)) WHERE `f`.`is_active` = 1 ORDER BY `f`.`view_count` DESC ;

